    {
      "activity_id": "ACT-1",
      "activity_name": "Port json-to-tuple processor module (U1)",
      "activity_description": "Extract logic from Spring XD json-to-tuple module, refactor to Spring Cloud Stream processor module structure, add configuration properties, and write unit/integration tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Port object-to-json processor module (U2)",
      "activity_description": "Adapt Spring XD object-to-json transformer into a standalone s-c-s processor module, configure Jackson serializer options, and implement automated tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Port script processor module (U3)",
      "activity_description": "Port script processor (supporting JSR-223 script evaluation such as Groovy) into s-c-s processor module, including script variable binding and execution context handling.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Port shell processor module (U4)",
      "activity_description": "Port shell execution processor to s-c-s, handling external process invocation, stdio/stdout stream piping, timeout handling, error handling, and integration tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Port splitter processor module (U5)",
      "activity_description": "Port Spring XD splitter logic (collection/array/delimiter payload splitting) to s-c-s processor module, including stream header preservation and unit testing.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Explore options to remove composed job (U6)",
      "activity_description": "Investigate Spring XD runtime resource lifecycle for composed jobs, evaluate memory footprint cleanup options, and create a proof-of-concept fix/proposal.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Explore options for ZK metadata persistence of composed jobs (U7)",
      "activity_description": "Analyze options to serialize and persist composed job definitions into ZooKeeper metadata nodes for failover recovery, and deliver a POC and technical decision document.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Design and implement BinderFactory abstraction (U8)",
      "activity_description": "Design `BinderFactory` interface and default implementation in s-c-s core, support dynamic lookup/creation of multiple binder instances, and refactor Spring Boot autoconfiguration.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration testing, documentation, and build setup",
      "activity_description": "Perform cross-module integration tests, update Maven/Gradle build definitions, and document usage of new processor modules and BinderFactory.",
      "most_likely_effort": 14
    }
  ],
